% Kuat variables
mu_kuat = 1.2748e6; % [km3 / s2]

kuat_day = 60 * 60 * 20;
hgeo_kuat = ((mu_kuat * (kuat_day)^2) / (4 * pi^2))^(1/3);

% Bador Variables
a_bador = 384400; % [km]
mu_bador = 4902.8005821478 * 10; % [km3 / s2]

% Given Tatooine Variables
gamma_plus_kuat = 0; % [rad]
v_inf_plus_kuat = 12.6285; % [km / s]
%%
%[text] ## Transfer to Bador
r_pfb_matches = zeros([100, 100]);
dV_kick = zeros([100, 100]);
dV_trans_geo = zeros([100, 100]);
dV_total = zeros([100, 100]);
for i = 1 : 100
    for j = 1 : 100
        r_p_dep = interp1([1, 100], [hgeo_kuat, a_bador], i);
        
        [e_dep, a_dep, v_dep_p, p_dep, h_dep] = hyperbola_parameters(mu_kuat, r_p_dep, v_inf_plus_kuat);
        
        v_bador = vis_viva(mu_kuat, a_bador, a_bador);
        v_dep_bador = vis_viva(mu_kuat, a_dep, a_bador);
        gamma_dep_bador = flight_path_angle(h_dep, a_bador, v_dep_bador);
%[text] ## Transfer to Bador
        e_trans_min = a_bador / ((hgeo_kuat + a_bador) / 2) - 1;
        e_trans_max = 1 + hgeo_kuat * v_inf_plus_kuat ^ 2 / mu_kuat;

        e_trans = interp1([1, 100], [e_trans_min, e_trans_max], j);

        a_trans = hgeo_kuat / (1 - e_trans);
        p_trans = a_trans * (1 - e_trans ^ 2);
        h_trans = sqrt(mu_kuat * p_trans);
        v_trans_geo = vis_viva(mu_kuat, a_trans, hgeo_kuat);
        gamma_trans_geo = flight_path_angle(h_trans, hgeo_kuat, v_trans_geo);
        v_geo = vis_viva(mu_kuat, hgeo_kuat, hgeo_kuat);
        dV_trans_geo(i, j) = law_of_cosines(v_geo, v_trans_geo, gamma_trans_geo);
        v_trans_bador = vis_viva(mu_kuat, a_trans, a_bador);
        gamma_trans_bador = flight_path_angle(h_trans, a_bador, v_trans_bador);
%[text] ## Flyby
        v_inf_plus = law_of_cosines(v_bador, v_dep_bador, gamma_dep_bador);
        v_inf_minus = law_of_cosines(v_trans_bador, v_bador, gamma_trans_bador);
        
        r_pfb_actual = 1738.2; % [km]
        
        dV_needed = law_of_cosines(v_trans_bador, v_dep_bador, gamma_trans_bador - gamma_dep_bador);
        delta_needed = acosd((v_inf_plus ^ 2 + v_inf_minus ^ 2 - dV_needed ^ 2) / (2 * v_inf_plus * v_inf_minus));
        
        r_pfbfunc = @(r_pfb_var) asind(1 / (1 + r_pfb_var * v_inf_minus ^ 2 / mu_bador)) + asind(1 / (1 + r_pfb_var * v_inf_plus ^ 2 / mu_bador)) - delta_needed;
        options = optimoptions('fsolve','Display','none');
        r_pfb_matches(i, j) = fsolve(r_pfbfunc, r_pfb_actual, options);
%[text] ## Post process (calculate incoming and outgoing flyby hyperbolas and kick delta v)
        delta_plus = 2 * asind(1 / (1 + r_pfb_matches(i, j) * v_inf_plus ^ 2 / mu_bador));
        [e_flyby_plus, a_flyby_plus, v_flyby_p_plus, p_flyby_plus, h_flyby_plus] = hyperbola_parameters(mu_bador, r_pfb_matches(i, j), v_inf_plus);
%[text] ## 
        [e_flyby_minus, a_flyby_minus, v_flyby_p_minus, p_flyby_minus, h_flyby_minbus] = hyperbola_parameters(mu_bador, r_pfb_matches(i, j), v_inf_minus);
        delta_minus = 2 * asind(1 / (1 + r_pfb_matches(i, j) * v_inf_minus ^ 2 / mu_bador));
        dV_kick(i, j) = v_flyby_p_plus - v_flyby_p_minus;
        dV_total(i, j) = dV_trans_geo(i, j) + dV_kick(i, j);
    end
end
%%

[X, Y] = meshgrid(linspace(hgeo_kuat, a_bador, 100), linspace(e_trans_min, e_trans_max, 100));

r_pfb_matches_filtered = r_pfb_matches;
r_pfb_matches_filtered(r_pfb_matches < r_pfb_actual) = nan;

figure %[output:35a30d8e]
pcolor(X / a_bador, Y, r_pfb_matches_filtered' / r_pfb_actual, FaceColor="flat",EdgeAlpha=0,HandleVisibility="off"); %[output:35a30d8e]
colorbar() %[output:35a30d8e]
xlabel("Periapsis Radius Departure Hyperbola [a_{bador}]") %[output:35a30d8e]
ylabel("GEO->Bador Transfer Eccentricity") %[output:35a30d8e]
title("Flyby Radius vs Transfer Eccentricity and Departure Periapsis") %[output:35a30d8e]
%%
dV_total_filtered = dV_total;
dV_total_filtered(r_pfb_matches < r_pfb_actual) = nan;

figure %[output:0bcc03af]
pcolor(X / a_bador, Y, dV_total_filtered', FaceColor="flat",EdgeAlpha=0,HandleVisibility="off"); %[output:0bcc03af]
colorbar() %[output:0bcc03af]
xlabel("Periapsis Radius Departure Hyperbola [a_{bador}]") %[output:0bcc03af]
ylabel("GEO->Bador Transfer Eccentricity") %[output:0bcc03af]
title("Total delta V vs Transfer Eccentricity and Departure Periapsis") %[output:0bcc03af]
%%
%[text] ## No flyby
[e_dep_no, a_dep_no, v_dep_p_no, p_dep_no, h_dep_no] = hyperbola_parameters(mu_kuat, hgeo_kuat, v_inf_plus_kuat) %[output:47b7e874] %[output:7df30668] %[output:55f204ce] %[output:36c945db] %[output:6dce6454]
v_dep_geo_no = vis_viva(mu_kuat, a_dep_no, hgeo_kuat) %[output:353c8e7d]
dV_total_no = v_dep_geo_no - v_geo %[output:4a49dfbd]
gamma_dep_geo_no = flight_path_angle(h_dep_no, hgeo_kuat, v_dep_p_no) %[output:7330e91d]
%%
dV_total_filtered = dV_total;
dV_total_filtered(r_pfb_matches < r_pfb_actual) = nan;
dV_total_filtered(dV_total > dV_total_no) = nan;

figure %[output:5ac7a73c]
pcolor(X / a_bador, Y, dV_total_filtered', FaceColor="flat",EdgeAlpha=0,HandleVisibility="off"); %[output:5ac7a73c]
colorbar() %[output:5ac7a73c]
xlabel("Periapsis Radius Departure Hyperbola [a_{bador}]") %[output:5ac7a73c]
ylabel("GEO->Bador Transfer Eccentricity") %[output:5ac7a73c]
title("Better Total delta V vs Transfer Eccentricity and Departure Periapsis") %[output:5ac7a73c]
%%
%[text] ## Plot Best Solution
% Recover best solution
[val, ij] = min(dV_total_filtered, [], "all") %[output:60de7909] %[output:50f39517]
i_best = mod(ij - 1, 100) + 1;
j_best = ceil(ij / 100);
%%

r_p_dep = interp1([1, 100], [hgeo_kuat, a_bador], i_best);
        
[e_dep, a_dep, v_dep_p, p_dep, h_dep] = hyperbola_parameters(mu_kuat, r_p_dep, v_inf_plus_kuat);

v_bador = vis_viva(mu_kuat, a_bador, a_bador);
v_dep_bador = vis_viva(mu_kuat, a_dep, a_bador);
gamma_dep_bador = flight_path_angle(h_dep, a_bador, v_dep_bador);

e_trans_min = a_bador / ((hgeo_kuat + a_bador) / 2) - 1;
e_trans_max = 1 + hgeo_kuat * v_inf_plus_kuat ^ 2 / mu_kuat;

e_trans = interp1([1, 100], [e_trans_min, e_trans_max], j_best);

a_trans = hgeo_kuat / (1 - e_trans);
p_trans = a_trans * (1 - e_trans ^ 2);
h_trans = sqrt(mu_kuat * p_trans);
v_trans_geo = vis_viva(mu_kuat, a_trans, hgeo_kuat);
gamma_trans_geo = flight_path_angle(h_trans, hgeo_kuat, v_trans_geo);
v_geo = vis_viva(mu_kuat, hgeo_kuat, hgeo_kuat);
dV_trans_geo_best = law_of_cosines(v_geo, v_trans_geo, gamma_trans_geo) %[output:3d9f81c2]
v_trans_bador = vis_viva(mu_kuat, a_trans, a_bador);
gamma_trans_bador = flight_path_angle(h_trans, a_bador, v_trans_bador);

v_inf_plus = law_of_cosines(v_bador, v_dep_bador, gamma_dep_bador);
v_inf_minus = law_of_cosines(v_trans_bador, v_bador, gamma_trans_bador);

dV_needed = law_of_cosines(v_trans_bador, v_dep_bador, gamma_trans_bador - gamma_dep_bador);
delta_needed = acosd((v_inf_plus ^ 2 + v_inf_minus ^ 2 - dV_needed ^ 2) / (2 * v_inf_plus * v_inf_minus));

r_pfb_best = r_pfb_matches(i_best, j_best);

delta_plus = 2 * asind(1 / (1 + r_pfb_best * v_inf_plus ^ 2 / mu_bador));
[e_flyby_plus, a_flyby_plus, v_flyby_p_plus, p_flyby_plus, h_flyby_plus] = hyperbola_parameters(mu_bador, r_pfb_best, v_inf_plus);
%[text] ## 
[e_flyby_minus, a_flyby_minus, v_flyby_p_minus, p_flyby_minus, h_flyby_minbus] = hyperbola_parameters(mu_bador, r_pfb_best, v_inf_minus);
delta_minus = 2 * asind(1 / (1 + r_pfb_best * v_inf_minus ^ 2 / mu_bador));
dV_kick_best = v_flyby_p_plus - v_flyby_p_minus %[output:31a338ac]
dV_total_best = dV_trans_geo_best + dV_kick_best %[output:7efa2178]

thetastar_bador_trans = acosd(1 / e_trans * (p_trans / a_bador - 1));
thetaster_bador_dep = acosd(1 / e_dep * (p_dep / a_bador - 1));

% Plot
figure %[output:1cb183fe]
orbitplot2D(hgeo_kuat, 0, 0 : 0.01 : 2 * pi, 0, "Geo", r_scale = a_bador, color = "g"); hold on %[output:1cb183fe]
orbitplot2D(a_bador, 0, 0 : 0.01 : 2 * pi, 0, "Bador", r_scale = a_bador, color = "b"); %[output:1cb183fe]
orbitplot2D(a_trans, e_trans, 0 : 0.001 : deg2rad(thetastar_bador_trans), 0, "Transfer", r_scale = a_bador, color = "r") %[output:1cb183fe]
orbitplot2D(a_dep, e_dep, deg2rad(thetaster_bador_dep):0.01:1.3, deg2rad(thetastar_bador_trans-thetaster_bador_dep), "Departure", r_scale = a_bador, color = "r") %[output:1cb183fe]
orbitplot2D(a_flyby_minus, e_flyby_minus, -2.2:0.01:0, deg2rad(95), "flyby in", r_scale = r_pfb_best * 30, origin = r_pfb_best * 30 * [cosd(thetastar_bador_trans); sind(thetastar_bador_trans)], color = "r") %[output:1cb183fe]
orbitplot2D(a_flyby_plus, e_flyby_plus, 0:0.01:1.6, deg2rad(95), "flyby out", r_scale = r_pfb_best * 30, origin = r_pfb_best * 30 * [cosd(thetastar_bador_trans); sind(thetastar_bador_trans)], color = "r") %[output:1cb183fe]
orbitplot2D(a_dep_no, e_dep_no, 0:0.01:deg2rad(94), deg2rad(100), "No flyby Dep", r_scale = a_bador) %[output:1cb183fe]
hold off; %[output:1cb183fe]
legend(Location="eastoutside") %[output:1cb183fe]
title("Kuat Centric Departure") %[output:1cb183fe]
axis equal %[output:1cb183fe]
%%
%[text] ## Helper Functions
function [v] = vis_viva(mu, a, r)
    v = sqrt(mu * (2 ./ r - 1 ./ a));
end

function [gamma] = flight_path_angle(h, r, v)
    gamma = acosd(h / (r * v));
    if imag(gamma) < 1e-5
        gamma = real(gamma);
    end
end

function [c] = law_of_cosines(a, b, gamma)
    c = sqrt(a ^ 2 + b ^ 2 - 2 * a * b * cosd(gamma));
end

function [e, a, v, p, h] = hyperbola_parameters(mu, r_p, v_inf)
    e = 1 + r_p * v_inf ^ 2 / mu;
    a = -mu / v_inf ^ 2;
    v = vis_viva(mu, a, r_p);
    p = a * (1 - e ^ 2);
    h = sqrt(mu * p);
end

